$ErrorActionPreference="Stop"
Set-StrictMode -Version 2.0
$RepoRoot=Split-Path -Parent $PSScriptRoot;Set-Location $RepoRoot
$Adb="C:\Users\User\AppData\Local\Android\Sdk\platform-tools\adb.exe";$Package="com.vladimir.messenger";$Apk=Join-Path $RepoRoot "android-app\app\build\outputs\apk\debug\app-debug.apk";$ExpectedApk="39111403F0715A019E90470879C05C328759937209E9EB2A9113B8162AAA0B30";$BuildState=Join-Path $env:TEMP "apu-m8-receipt-fanout-state.json";$ExpectedBuildState="6F2E47D2202E8C51BC1F337BA1D5C9F070A9F52499B4D7825EB2B29E306A51CB";$StatePath=Join-Path $env:TEMP "apu-m8-receipt-fanout-phone-update.json"
if(Test-Path $StatePath){throw "Fanout phone update already attempted; preserve evidence"};if((Get-FileHash $BuildState -Algorithm SHA256).Hash -ne $ExpectedBuildState){throw "Build state mismatch"};if((Get-FileHash $Apk -Algorithm SHA256).Hash -ne $ExpectedApk){throw "APK mismatch"}
$Phones=@([pscustomobject]@{Name="Anna";Serial="AUYF6R5923006121"},[pscustomobject]@{Name="Zhenya";Serial="3B665800EES00000"},[pscustomobject]@{Name="Stas";Serial="11567254BK001192"});$Result=[ordered]@{schema=1;outcome="INCOMPLETE_DO_NOT_REPEAT";startedUtc=(Get-Date).ToUniversalTime().ToString("o");apkSha256=$ExpectedApk;phones=@();replaceInstallUsed=$true;uninstallUsed=$false;dataCleared=$false;logcatCleared=$false};$Result|ConvertTo-Json -Depth 8|Set-Content $StatePath -Encoding UTF8
try{foreach($Phone in $Phones){$Serial=$Phone.Serial;$Before=@(& $Adb -s $Serial shell dumpsys package $Package);$BeforeVersion=(($Before|Where-Object{$_ -match "^\s*versionName="}|Select-Object -First 1) -as [string]).Trim();if($BeforeVersion -ne "versionName=v11.16.22"){throw "$($Phone.Name) pre-version mismatch"};$BeforePrefs=(& $Adb -s $Serial exec-out run-as $Package cat shared_prefs/p2p_prefs.xml 2>$null)-join"`n";if($BeforePrefs -notmatch 'identity_created"\s+value="true'){throw "$($Phone.Name) identity missing"};$Install=((& $Adb -s $Serial install -r $Apk)-join" ").Trim();if($LASTEXITCODE -ne 0 -or $Install -notmatch "Success"){throw "$($Phone.Name) update failed"};$Launch=((& $Adb -s $Serial shell am start -W -n "$Package/.MainActivity")-join" ").Trim();Start-Sleep 8;$Dump=@(& $Adb -s $Serial shell dumpsys package $Package);$Version=(($Dump|Where-Object{$_ -match "^\s*versionName="}|Select-Object -First 1) -as [string]).Trim();$Prefs=(& $Adb -s $Serial exec-out run-as $Package cat shared_prefs/p2p_prefs.xml 2>$null)-join"`n";$Identity=$Prefs -match 'identity_created"\s+value="true';$Marker=@(& $Adb -s $Serial shell run-as $Package ls no_backup 2>$null|Where-Object{$_ -match "apu_identity_device_v1"}).Count -eq 1;$PidText=((& $Adb -s $Serial shell pidof $Package)-join" ").Trim();if($Version -ne "versionName=v11.16.23" -or -not $Identity -or -not $Marker -or -not $PidText){throw "$($Phone.Name) post-update verification failed"};$Entry=[pscustomobject]@{Name=$Phone.Name;Serial=$Serial;beforeVersion=$BeforeVersion;version=$Version;identity=$Identity;marker=$Marker;processId=$PidText;install=$Install;launch=$Launch};$Result.phones+=@($Entry);$Result|ConvertTo-Json -Depth 8|Set-Content $StatePath -Encoding UTF8;Write-Host "$($Phone.Name): v11.16.23 identity=$Identity marker=$Marker PID=$PidText"};$Result.outcome="PASS";$Result.completedUtc=(Get-Date).ToUniversalTime().ToString("o")}finally{$Result|ConvertTo-Json -Depth 8|Set-Content $StatePath -Encoding UTF8}
$Hash=(Get-FileHash $StatePath -Algorithm SHA256).Hash;Write-Host "`nOutcome: $($Result.outcome)";Write-Host "State: $StatePath";Write-Host "State SHA256: $Hash";Write-Host "Phones updated/preserved: $($Result.phones.Count)/3";Write-Host "M8 RECEIPT FANOUT PHONE UPDATE PASS"
